sys_script_include.script:
var DeliveryDateUtils = Class.create();
DeliveryDateUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    initialize: function() {},
	// GET-Methode zum Abrufen der offenen Requested Items
    getRequestedItems: function() {
        var requestedItems = [];
        var gr = new GlideRecord('sc_req_item');
        gr.addQuery('state', '=', 1);
        gr.orderByDesc('sys_created_on');
        gr.query();

        while (gr.next()) {
            requestedItems.push({
                sys_id: gr.getValue('sys_id'),
                number: gr.getValue('number'),
                short_description: gr.getValue('short_description')
            });
        }
        return requestedItems;
    },

});
